import java.io.BufferedReader; import java.io.InputStreamReader; import java.io.PrintWriter; import java.io.BufferedOutputStream; import java.util.StringTokenizer; public class Main { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out)); StringTokenizer st = null; String line = br.readLine(); if (line == null) return; int t = Integer.parseInt(line.trim()); while (t-- > 0) { while (st == null || !st.hasMoreTokens()) { String l = br.readLine(); if (l == null) break; st = new StringTokenizer(l); } int n = Integer.parseInt(st.nextToken()); int k = Integer.parseInt(st.nextToken()); int[] a = new int[k]; for (int i = 0; i < k; i++) { a[i] = Integer.parseInt(st.nextToken()); } int[] p = new int[n + 1]; int prev = 0; for (int i = 0; i < k; i++) { int curr = a[i]; for (int j = prev + 1; j <= curr; j++) { p[j] = prev + (curr - j + 1); } prev = curr; } StringBuilder sb = new StringBuilder(); for (int i = 1; i <= n; i++) { sb.append(p[i]); if (i < n) sb.append(" "); } out.println(sb.toString()); } out.flush(); out.close(); } }